from collections import Counter

def numTilePossibilities(tiles: str) -> int:
    count = Counter(tiles)
    total = 0

    def backtrack(remaining):
        nonlocal total
        if remaining:
            total += 1
        for char in remaining:
            if count[char] > 0:
                count[char] -= 1
                backtrack(remaining)
                count[char] += 1

    backtrack(count)
    return total
